/**
 * Every priced dish on the canteen's menu boards, read from 64 photos taken
 * on 21 October 2569 (2026). One photo set per stall, named by stall number
 * (3A, 3B and so on), kept in the TUSU Google Drive canteen folder.
 *
 * The Thai and English names, prices and size or topping variants are as
 * the boards show them. Type, course, protein, cooking style,
 * temperature and "wet" were judged from the name and the picture: nobody
 * asked the stalls. "contains" is a deliberately broad guess at allergens
 * (fish sauce, soy sauce, shrimp paste and batter included): it errs
 * towards listing too much and is never a guarantee. Vegetarian is true only where the board says so or the item plainly
 * has no meat, fish or seafood.
 *
 * Generated from the transcription and mirrored, row for row, in
 * data/canteen-survey.csv for the Sanity importer. Change both together.
 */

import type { Allergen, CookingStyle, DishCourse, DishType, Protein, Temperature } from "@/lib/sanity/types";

/** The day the menu boards were photographed. */
export const SURVEY_DATE = "2026-10-21";

export interface SurveyVariant {
  th: string;
  en: string;
  delta: number;
}

/** A topping or extra a stall sells only with something else. No `courses` or `dishes` means every item at the stall. */
export interface SurveyAddOn {
  th: string;
  en: string;
  delta: number;
  courses?: DishCourse[];
  dishes?: string[];
}

export interface SayPhrase {
  th: string;
  romanised: string;
}

export interface SurveyDish {
  stall: number;
  slug: string;
  th: string;
  en: string;
  /** What to say to order it, one phrase per choice. */
  sayAs?: SayPhrase[];
  /** The number the stall's board gives the dish. */
  menuNumber?: string;
  price: number;
  variants?: SurveyVariant[];
  type: DishType;
  course: DishCourse;
  protein: Protein[];
  /** Allergens it probably contains, guessed from the name and usual recipe, sauces and batters included. */
  contains?: Allergen[];
  style?: CookingStyle;
  temperature: Temperature;
  wet: boolean;
  vegetarian: boolean;
  /** Canonical dish id, for the cross-stall comparison and the explainer. */
  canonical?: string;
  /** The photo the row was read from, without ".jpg". */
  photo: string;
}

